using System.Globalization;

namespace Billing;

/// <summary>Parses application settings, returning a fallback when the raw value is missing or invalid.</summary>
public static class AppSettingsHelper
{
    public static int ParseIntSetting(string? raw, int fallback)
    {
        if (raw is null)
            return fallback;

        if (raw.StartsWith("0x", StringComparison.OrdinalIgnoreCase) || raw.StartsWith("0X", StringComparison.OrdinalIgnoreCase))
            return int.TryParse(raw.AsSpan(2), NumberStyles.AllowHexSpecifier, CultureInfo.InvariantCulture, out var hex) ? hex : fallback;

        return int.TryParse(raw, out var v) ? v : fallback;
    }

